PARTS = [
 {"t": "The Mechanics: How Money Is Made and Moved", "d": "Before naming anyone, the working parts: what money is, who creates it, what interest does, what a bond, a share and a bet are, and what happens when money crosses a border."},
 {"t": "The Top: Who Sets the Price of Money", "d": "A few committees and firms that no voter chose set the interest rate, write the rules for banks, lend to governments in trouble and grade every borrower on earth."},
 {"t": "The Core: Banks and the Finance Outside Them", "d": "Twenty-nine banks are too large to be allowed to fail, and more than half of the world's financial assets now sit with firms that are not banks at all."},
 {"t": "The Owners: Who Holds the Shares", "d": "Three fund managers are the largest shareholder in most big companies, a tenth of households own nearly all the shares, and companies are run to pay them."},
 {"t": "The Exits: Where Money Goes to Avoid Tax", "d": "Profit is booked where tax is lowest and wealth is held where questions are fewest, and the countries that lose the most are often the poorest."},
 {"t": "The Borrower Nations: Debt as a Lever", "d": "Governments borrow in a market that charges poor countries several times what it charges rich ones, and the interest is paid before the schools and clinics."},
 {"t": "The Household: What Reaches You", "d": "At the bottom of the chain is a household that borrows to live, pays a fee to move its own money, or has no account at all."},
 {"t": "The Shield, and the Whole Chain", "d": "Why the arrangement stays in place, and the full chain from the committee that sets the rate to the person who pays it."},
]
