    return dict(y=y, p=p, ll=ll, z=z, cap=cap, t=t, src=src, add=add or {}, arcs=arcs or [], an=an or [], pins=pins or [], pl=pl or [], ex=ex or [], reg=reg, w=w, data=data, note=note)
